export const EVIDENCE = [{id:"EMF",en:"EMF Level 5",el:"EMF Επίπεδο 5",short:"EMF",letter:"E"},{id:"DOTS",en:"D.O.T.S. Projector",el:"D.O.T.S. Προβολέας",short:"DOTS",letter:"D"},{id:"UV",en:"Ultraviolet",el:"Υπεριώδες (UV)",short:"UV",letter:"U"},{id:"ORB",en:"Ghost Orb",el:"Ghost Orb",short:"ORB",letter:"O"},{id:"WRITING",en:"Ghost Writing",el:"Γραφή φαντάσματος",short:"BOOK",letter:"W"},{id:"SPIRIT_BOX",en:"Spirit Box",el:"Spirit Box",short:"BOX",letter:"B"},{id:"FREEZING",en:"Freezing Temperatures",el:"Παγωμένες θερμοκρασίες",short:"FRZ",letter:"F"}];
export const GHOSTS = [
  {id:"banshee",name:"Banshee",evidence:["ORB","UV","DOTS"],huntAt:50,huntMin:12,huntMax:87,huntEn:"50% – but of its TARGET's sanity, not the team average",huntEl:"50% – αλλά της λογικής του ΣΤΟΧΟΥ της, όχι του μέσου όρου",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Picks one player as its target and hunts only them while they are inside.","More singing ghost events than any other ghost.","Distinct wailing scream on the Parabolic Microphone / Sound Recorder.","Always a female name."],tellsEl:["Διαλέγει έναν παίκτη ως στόχο και κυνηγά μόνο αυτόν όσο είναι μέσα.","Κάνει περισσότερα «τραγουδιστά» events από κάθε άλλο φάντασμα.","Χαρακτηριστικό ουρλιαχτό στο Parabolic Microphone / Sound Recorder.","Πάντα γυναικείο όνομα."]},
  {id:"dayan",name:"Dayan",evidence:["EMF","ORB","SPIRIT_BOX"],huntAt:50,huntMin:45,huntMax:65,huntEn:"50% – 65% while the nearest player within 10 m is moving, 45% while they stand still",huntEl:"50% – 65% όσο ο πλησιέστερος παίκτης εντός 10 μ. κινείται, 45% όσο στέκεται ακίνητος",speedMin:1.2,speedMax:2.25,speedEn:"1.7 m/s when nobody is within 10 m · fixed 2.25 m/s while the nearest player within 10 m moves, fixed 1.2 m/s while they stand still (also through floors)",speedEl:"1.7 m/s όταν κανείς δεν είναι εντός 10 μ. · σταθερά 2.25 m/s όσο ο πλησιέστερος παίκτης εντός 10 μ. κινείται, σταθερά 1.2 m/s όσο στέκεται (και μέσα από ορόφους)",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Reacts to movement: stand still near it and it crawls at 1.2 m/s, move and it sprints at 2.25 m/s – even if it cannot see you.","A player standing still in a nearby hiding spot slows it down for everyone else.","Always female: a male name, model or voice rules it out (the Banshee is the only other ghost like this)."],tellsEl:["Αντιδρά στην κίνηση: μείνε ακίνητος κοντά της και σέρνεται με 1.2 m/s, κινήσου και ορμάει με 2.25 m/s – ακόμη κι αν δεν σε βλέπει.","Παίκτης που στέκεται ακίνητος σε κοντινή κρυψώνα την επιβραδύνει για όλους.","Πάντα γυναίκα: αντρικό όνομα, μοντέλο ή φωνή την αποκλείει (η Banshee είναι το μόνο άλλο τέτοιο φάντασμα)."]},
  {id:"demon",name:"Demon",evidence:["FREEZING","UV","WRITING"],huntAt:70,huntMin:70,huntMax:100,huntEn:"70% – and its ability can start a hunt at ANY sanity",huntEl:"70% – και με την ικανότητά του ξεκινά κυνήγι σε ΟΠΟΙΑΔΗΠΟΤΕ λογική",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:60,cooldown:20,isNew:false,tellsEn:["Incense only stops hunts for 60 s instead of 90 s.","Can hunt again just 20 s after a hunt ends.","Crucifix protects a 50% larger area against it.","Early, very frequent hunts with a crucifix burning fast = Demon."],tellsEl:["Το θυμίαμα σταματά κυνήγια μόνο για 60 δ αντί 90.","Μπορεί να ξανακυνηγήσει μόλις 20 δ μετά το τέλος κυνηγιού.","Ο σταυρός καλύπτει 50% μεγαλύτερη περιοχή εναντίον του.","Πρώιμα, πολύ συχνά κυνήγια και σταυρός που καίγεται γρήγορα = Demon."]},
  {id:"deogen",name:"Deogen",evidence:["SPIRIT_BOX","WRITING","DOTS"],huntAt:40,huntMin:40,huntMax:40,huntEn:"40%",huntEl:"40%",speedMin:0.4,speedMax:3.0,speedEn:"3.0 m/s when far (> 6 m) · slows to 0.4 m/s next to you",speedEl:"3.0 m/s από μακριά (> 6 μ.) · πέφτει στο 0.4 m/s δίπλα σου",los:false,fakeOrb:false,guaranteed:"SPIRIT_BOX",smudge:90,cooldown:25,isNew:false,tellsEn:["Always knows where every player is – hiding is useless, but you can loop it.","Heavy breathing on the Spirit Box when you ask within 1 m of it.","Rushes across the map then crawls when it reaches you.","Only appears for hosts at Level 30 or above."],tellsEl:["Ξέρει πάντα πού είναι όλοι – το κρύψιμο είναι άχρηστο, αλλά το κάνεις κύκλους.","Βαριά ανάσα στο Spirit Box αν ρωτήσεις εντός 1 μ.","Τρέχει από μακριά και σέρνεται όταν σε φτάσει.","Εμφανίζεται μόνο αν ο host είναι Level 30+."]},
  {id:"gallu",name:"Gallu",evidence:["EMF","SPIRIT_BOX","UV"],huntAt:50,huntMin:40,huntMax:60,huntEn:"Normal 50% · Enraged 60% · Weakened 40%",huntEl:"Κανονικό 50% · Εξαγριωμένο 60% · Εξασθενημένο 40%",speedMin:1.36,speedMax:1.96,speedEn:"Normal 1.7 · Enraged 1.96 · Weakened 1.36 m/s",speedEl:"Κανονικό 1.7 · Εξαγριωμένο 1.96 · Εξασθενημένο 1.36 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Protective gear ENRAGES it: burning a crucifix, the end of an incense blind during a hunt, or stepping in salt (2 s later) – enraged it hunts from 60% at 1.96 m/s, and incense/crucifix/salt work less.","When a hunt ends while it is enraged it becomes WEAKENED: 1.36 m/s, hunts only below 40%, protection works better – and it leaves 6 salt footprints instead of 4.","Salt test: lay several piles on its path – a normal Gallu steps in the first, then (enraged) walks over the rest without disturbing them. Only the Wraith, which never steps in salt, looks similar."],tellsEl:["Ο προστατευτικός εξοπλισμός το ΕΞΑΓΡΙΩΝΕΙ: κάψιμο σταυρού, το τέλος της τύφλωσης από θυμίαμα σε κυνήγι, ή πάτημα σε αλάτι (2 δ. μετά) – εξαγριωμένο κυνηγά από 60% με 1.96 m/s και θυμίαμα/σταυρός/αλάτι πιάνουν λιγότερο.","Όταν τελειώσει κυνήγι ενώ είναι εξαγριωμένο, ΕΞΑΣΘΕΝΕΙ: 1.36 m/s, κυνηγά μόνο κάτω από 40%, η προστασία πιάνει περισσότερο – και αφήνει 6 πατημασιές αλατιού αντί 4.","Τεστ αλατιού: βάλε αρκετούς σωρούς στη διαδρομή του – ο κανονικός Gallu πατά στον πρώτο και μετά (εξαγριωμένος) περνά πάνω από τους υπόλοιπους χωρίς να τους ανακατέψει. Μόνο το Wraith, που δεν πατά ποτέ σε αλάτι, μοιάζει."]},
  {id:"goryo",name:"Goryo",evidence:["EMF","UV","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:"DOTS",smudge:90,cooldown:25,isNew:false,tellsEn:["D.O.T.S. silhouette only shows on a Video Camera, and only when nobody is in the room.","Rarely leaves its favourite room and never changes it."],tellsEl:["Η σιλουέτα D.O.T.S. φαίνεται μόνο σε Video Camera και μόνο όταν κανείς δεν είναι στο δωμάτιο.","Σπάνια φεύγει από το αγαπημένο του δωμάτιο και δεν το αλλάζει ποτέ."]},
  {id:"hantu",name:"Hantu",evidence:["ORB","FREEZING","UV"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.4,speedMax:2.7,speedEn:"1.4 m/s in warm rooms (≥ 15 °C) up to 2.7 m/s below 3 °C · no LOS boost",speedEl:"1.4 m/s σε ζεστά δωμάτια (≥ 15 °C) έως 2.7 m/s κάτω από 3 °C · χωρίς επιτάχυνση LOS",los:false,fakeOrb:false,guaranteed:"FREEZING",smudge:90,cooldown:25,isNew:false,tellsEn:["Visible freezing breath during a hunt while the fuse box is off.","Never turns the fuse box on. Keep it ON to keep the Hantu slow.","Freezing is always one of its evidences – a Hantu without freezing is not a Hantu."],tellsEl:["Ορατή παγωμένη ανάσα στο κυνήγι όσο ο πίνακας ρεύματος είναι κλειστός.","Δεν ανοίγει ποτέ τον πίνακα. Κράτα τον ΑΝΟΙΧΤΟ για να μένει αργό.","Το Freezing είναι πάντα στις αποδείξεις του."]},
  {id:"jinn",name:"Jinn",evidence:["EMF","FREEZING","UV"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:2.5,speedEn:"1.7 m/s · 2.5 m/s when fuse box is ON, it sees you and you are > 3 m away",speedEl:"1.7 m/s · 2.5 m/s όταν ο πίνακας είναι ΑΝΟΙΧΤΟΣ, σε βλέπει και είσαι > 3 μ. μακριά",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Ability: EMF 2 or 5 at the fuse box while draining 25% sanity from nearby players.","Never turns the fuse box off directly.","Turn the breaker OFF to remove its speed boost."],tellsEl:["Ικανότητα: EMF 2 ή 5 στον πίνακα ενώ ρουφά 25% λογικής από κοντινούς παίκτες.","Δεν κλείνει ποτέ τον πίνακα από μόνο του.","Κλείσε τον πίνακα για να χάσει την επιτάχυνση."]},
  {id:"mare",name:"Mare",evidence:["ORB","SPIRIT_BOX","WRITING"],huntAt:60,huntMin:40,huntMax:60,huntEn:"60% in the dark · only 40% with the lights on",huntEl:"60% στο σκοτάδι · μόνο 40% με τα φώτα ανοιχτά",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["May turn a light off within a second after you switch it on within 4 m of it (1 in 7 chance) – a light that goes off in the middle of a ghost event is conclusive.","Never turns a light on (any ghost that does is not a Mare). Shatters lights in ghost events more often than others.","Light in its room is the key: lights on there drop its hunt threshold to 40% and make it roam away more often; in the dark it hunts from 60%. Only the room's own lights count, not flashlights or firelights."],tellsEl:["Μπορεί να σβήσει ένα φως μέσα σε ένα δευτερόλεπτο αφού το ανάψεις εντός 4 μ. από αυτό (πιθανότητα 1 στις 7) – φως που σβήνει στη μέση ενός ghost event είναι απόδειξη.","Δεν ανάβει ποτέ φως (όποιο φάντασμα ανάβει φως δεν είναι Mare). Σπάει φώτα σε events πιο συχνά από τα άλλα.","Το φως στο δωμάτιό του είναι το κλειδί: με τα φώτα του δωματίου ανοιχτά κυνηγά μόνο από 40% και φεύγει πιο συχνά σε περιπλάνηση· στο σκοτάδι κυνηγά από 60%. Μετρούν μόνο τα φώτα του δωματίου, όχι φακοί ή firelights."]},
  {id:"moroi",name:"Moroi",evidence:["SPIRIT_BOX","FREEZING","WRITING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.5,speedMax:2.25,speedEn:"1.5 m/s at high sanity → 2.25 m/s at very low sanity (+0.083 per 5% below threshold)",speedEl:"1.5 m/s σε υψηλή λογική → 2.25 m/s σε πολύ χαμηλή (+0.083 ανά 5% κάτω από το όριο)",los:true,fakeOrb:false,guaranteed:"SPIRIT_BOX",smudge:90,cooldown:25,isNew:false,tellsEn:["Curses whoever gets a Spirit Box response, hears it on the Parabolic Microphone or tries the Sound Recorder: sanity drains twice as fast, light no longer slows it, until that player takes sanity medication.","Speed depends on average sanity, not time: 1.5 m/s above 45%, +0.083 m/s per 5% below, 2.25 m/s near 0% – and it still speeds up on line of sight (up to 3.71 m/s).","Incense blinds it for 7 s during a hunt instead of 5 s.","Test: everyone takes sanity medication mid-hunt – if the ghost suddenly slows, it is a Moroi."],tellsEl:["Καταριέται όποιον πάρει απάντηση στο Spirit Box, το ακούσει στο Parabolic ή δοκιμάσει το Sound Recorder: η λογική πέφτει με διπλή ταχύτητα, το φως δεν βοηθά, μέχρι ο παίκτης να πάρει χάπια λογικής.","Η ταχύτητα εξαρτάται από τη μέση λογική, όχι από τον χρόνο: 1.5 m/s πάνω από 45%, +0.083 m/s ανά 5% χαμηλότερα, 2.25 m/s κοντά στο 0% – και επιταχύνει κανονικά με οπτική επαφή (έως 3.71 m/s).","Το θυμίαμα το τυφλώνει για 7 δ. στο κυνήγι αντί για 5 δ.","Τεστ: όλοι παίρνουν χάπια λογικής μέσα στο κυνήγι – αν το φάντασμα επιβραδύνει απότομα, είναι Moroi."]},
  {id:"myling",name:"Myling",evidence:["EMF","UV","WRITING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Footsteps during a hunt are audible only within ~12 m (others ~20 m) – it arrives quietly.","More frequent paranormal sounds on the Parabolic Microphone."],tellsEl:["Τα βήματα στο κυνήγι ακούγονται μόνο εντός ~12 μ. (τα άλλα ~20 μ.) – έρχεται αθόρυβα.","Πιο συχνοί παραφυσικοί ήχοι στο Parabolic Microphone."]},
  {id:"obake",name:"Obake",evidence:["EMF","ORB","UV"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:"UV",smudge:90,cooldown:25,isNew:false,tellsEn:["Only a 75% chance to leave fingerprints on each interaction.","Can leave unique prints: six-finger hand or two-finger print on light switches.","Its ability halves the remaining time of every fingerprint on the map – prints can vanish early.","May briefly change its model during a hunt."],tellsEl:["Μόνο 75% πιθανότητα να αφήσει αποτυπώματα σε κάθε αλληλεπίδραση.","Μπορεί να αφήσει ειδικά αποτυπώματα: χέρι με έξι δάχτυλα ή δύο δάχτυλα σε διακόπτη.","Η ικανότητά του μειώνει στο μισό τον υπόλοιπο χρόνο κάθε αποτυπώματος στον χάρτη – τα αποτυπώματα μπορεί να σβήσουν νωρίς.","Μπορεί να αλλάξει στιγμιαία μορφή στο κυνήγι."]},
  {id:"obambo",name:"Obambo",evidence:["UV","WRITING","DOTS"],huntAt:65,huntMin:10,huntMax:65,huntEn:"Calm 10% · Aggressive 65% – switches state every ~2 minutes",huntEl:"Ήρεμο 10% · Επιθετικό 65% – αλλάζει κατάσταση κάθε ~2 λεπτά",speedMin:1.45,speedMax:1.96,speedEn:"Calm 1.45 m/s · Aggressive 1.96 m/s (can switch mid-hunt)",speedEl:"Ήρεμο 1.45 m/s · Επιθετικό 1.96 m/s (αλλάζει και μέσα στο κυνήγι)",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Always starts calm, then alternates every ~2 min; can change state during a hunt.","Hunts that start in the aggressive state are ~20% shorter.","Early hunt at 60%+ then total silence until sanity is almost gone = Obambo.","Easily confused with The Twins – watch for the speed change inside one hunt."],tellsEl:["Ξεκινά πάντα ήρεμο, μετά εναλλάσσεται κάθε ~2 λεπτά· αλλάζει και μέσα στο κυνήγι.","Κυνήγια που ξεκινούν επιθετικά είναι ~20% πιο σύντομα.","Πρώιμο κυνήγι στο 60%+ και μετά σιωπή μέχρι να εξαντληθεί η λογική = Obambo.","Μπερδεύεται με τους Twins – πρόσεξε την αλλαγή ταχύτητας μέσα στο ίδιο κυνήγι."]},
  {id:"oni",name:"Oni",evidence:["EMF","FREEZING","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Much more active when players are nearby; its events drain extra sanity.","More visible during hunts (blinks less).","Never does the 'airball' (mist) ghost event – seeing one rules out Oni."],tellsEl:["Πολύ πιο ενεργό όταν υπάρχουν παίκτες κοντά· τα events του ρουφούν επιπλέον λογική.","Πιο ορατό στα κυνήγια (αναβοσβήνει λιγότερο).","Δεν κάνει ποτέ το event της ομίχλης (airball) – αν το δεις, δεν είναι Oni."]},
  {id:"onryo",name:"Onryo",evidence:["ORB","SPIRIT_BOX","FREEZING"],huntAt:60,huntMin:60,huntMax:100,huntEn:"60% – and at ANY sanity after it blows out a 3rd flame",huntEl:"60% – και σε ΟΠΟΙΑΔΗΠΟΤΕ λογική αφού σβήσει 3η φλόγα",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["A lit candle / firelight within 4 m blocks its hunts like a crucifix (and gets blown out instead).","Blows out candles far more often than other ghosts.","Every third flame it extinguishes triggers a hunt attempt."],tellsEl:["Αναμμένο κερί εντός 4 μ. μπλοκάρει κυνήγι όπως ο σταυρός (και σβήνει αντί γι' αυτό).","Σβήνει κεριά πολύ πιο συχνά από άλλα φαντάσματα.","Κάθε τρίτη φλόγα που σβήνει προκαλεί απόπειρα κυνηγιού."]},
  {id:"phantom",name:"Phantom",evidence:["SPIRIT_BOX","UV","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Taking a photo during a ghost event makes it vanish – and the ghost is missing from the photo.","Looking at it drains sanity faster.","Less visible during hunts (longer invisible phases).","Occasionally walks to a random player."],tellsEl:["Φωτογραφία σε ghost event το εξαφανίζει – και το φάντασμα λείπει από τη φωτογραφία.","Αν το κοιτάς, η λογική πέφτει πιο γρήγορα.","Λιγότερο ορατό στα κυνήγια (μεγαλύτερες αόρατες φάσεις).","Περιστασιακά περπατά προς τυχαίο παίκτη."]},
  {id:"poltergeist",name:"Poltergeist",evidence:["SPIRIT_BOX","UV","WRITING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Can throw many objects at once (explosion) – each thrown item drains 2% sanity from nearby players.","Throws objects harder and more often.","Powerless in an empty room: remove throwables and it goes quiet."],tellsEl:["Μπορεί να πετάξει πολλά αντικείμενα μαζί – κάθε ένα ρουφά 2% λογικής από κοντινούς παίκτες.","Πετά πιο δυνατά και πιο συχνά.","Ανίσχυρο σε άδειο δωμάτιο: μάζεψε τα αντικείμενα και ησυχάζει."]},
  {id:"raiju",name:"Raiju",evidence:["EMF","ORB","DOTS"],huntAt:50,huntMin:50,huntMax:65,huntEn:"50% – 65% while active electronic equipment is nearby",huntEl:"50% – 65% όσο υπάρχει ενεργός ηλεκτρονικός εξοπλισμός κοντά",speedMin:1.7,speedMax:2.5,speedEn:"1.7 m/s · fixed 2.5 m/s near active electronics on its floor (6 m small / 8 m medium / 10 m large maps)",speedEl:"1.7 m/s · σταθερά 2.5 m/s κοντά σε ενεργά ηλεκτρονικά στον όροφό του (6 μ. μικροί / 8 μ. μεσαίοι / 10 μ. μεγάλοι χάρτες)",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Interferes with electronics from 15 m instead of 10 m during hunts – interference at that range is only a hint, not a speed boost.","Active equipment (held, placed or dropped on) near it makes it faster; keeping electronics off or away only keeps it at normal speed – it never gets slower than 1.7 m/s.","Test: leave one item switched on at your hiding spot – footsteps that suddenly speed up near it point to a Raiju."],tellsEl:["Επηρεάζει τα ηλεκτρονικά από 15 μ. αντί 10 στα κυνήγια – η παρεμβολή σε τέτοια απόσταση είναι μόνο ένδειξη, όχι επιτάχυνση.","Ενεργός εξοπλισμός (στο χέρι, τοποθετημένος ή πεταμένος ανοιχτός) κοντά του το κάνει πιο γρήγορο· με τα ηλεκτρονικά κλειστά ή μακριά απλώς μένει στην κανονική ταχύτητα – ποτέ πιο αργό από 1.7 m/s.","Τεστ: άφησε ένα αντικείμενο ανοιχτό στην κρυψώνα σου – βήματα που επιταχύνουν ξαφνικά κοντά του δείχνουν Raiju."]},
  {id:"revenant",name:"Revenant",evidence:["ORB","FREEZING","WRITING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.0,speedMax:3.0,speedEn:"1.0 m/s when it has not found you · 3.0 m/s as soon as it detects a player",speedEl:"1.0 m/s όσο δεν σε έχει βρει · 3.0 m/s μόλις εντοπίσει παίκτη",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Extremely slow footsteps that suddenly become a sprint when it spots you.","Keeps its fast speed briefly after losing you – hide, do not run."],tellsEl:["Πολύ αργά βήματα που ξαφνικά γίνονται σπριντ όταν σε δει.","Κρατά την ταχύτητα λίγο αφού σε χάσει – κρύψου, μην τρέχεις."]},
  {id:"shade",name:"Shade",evidence:["EMF","FREEZING","WRITING"],huntAt:35,huntMin:35,huntMax:35,huntEn:"35%",huntEl:"35%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Will not hunt while a player is in the same room as it.","Very few interactions; more likely to appear as a shadow.","Activity rises as average sanity drops."],tellsEl:["Δεν κυνηγά όσο ένας παίκτης είναι στο ίδιο δωμάτιο.","Πολύ λίγες αλληλεπιδράσεις· εμφανίζεται συχνά ως σκιά.","Η δραστηριότητα αυξάνεται όσο πέφτει η λογική."]},
  {id:"spirit",name:"Spirit",evidence:["EMF","SPIRIT_BOX","WRITING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:180,cooldown:25,isNew:false,tellsEn:["No special ability – identified by elimination.","Incense blocks its hunts for 180 s instead of 90 s: smudge, then wait and see."],tellsEl:["Καμία ειδική ικανότητα – ταυτοποιείται με αποκλεισμό.","Το θυμίαμα μπλοκάρει κυνήγι για 180 δ αντί 90: κάπνισε και περίμενε."]},
  {id:"thaye",name:"Thaye",evidence:["ORB","WRITING","DOTS"],huntAt:75,huntMin:15,huntMax:75,huntEn:"75% when young – drops as it ages, down to 15%",huntEl:"75% όσο είναι «νέο» – πέφτει όσο γερνά, μέχρι 15%",speedMin:1.0,speedMax:2.75,speedEn:"2.75 m/s at the start → 1.0 m/s when fully aged · no LOS boost",speedEl:"2.75 m/s στην αρχή → 1.0 m/s όταν «γεράσει» · χωρίς επιτάχυνση LOS",los:false,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Ages every 1–2 min while players are near it: slower, calmer, hunts later.","Hyperactive and fast at the beginning, almost harmless at the end.","Ask the Ouija board its age twice – the answer grows."],tellsEl:["«Γερνά» κάθε 1–2 λεπτά όσο είναι παίκτες κοντά: πιο αργό, πιο ήρεμο, κυνηγά αργότερα.","Υπερδραστήριο και γρήγορο στην αρχή, σχεδόν ακίνδυνο στο τέλος.","Ρώτα το Ouija την ηλικία του δύο φορές – η απάντηση μεγαλώνει."]},
  {id:"mimic",name:"The Mimic",evidence:["SPIRIT_BOX","FREEZING","UV"],huntAt:100,huntMin:10,huntMax:100,huntEn:"Depends on the ghost it is copying (anything from 10% to 100%)",huntEl:"Εξαρτάται από το φάντασμα που μιμείται (από 10% έως 100%)",speedMin:0.4,speedMax:3.0,speedEn:"Copies the speed of the ghost it is currently mimicking",speedEl:"Αντιγράφει την ταχύτητα του φαντάσματος που μιμείται",los:true,fakeOrb:true,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["ALWAYS shows Ghost Orbs as a fake 4th evidence – orbs plus Spirit Box / Freezing / UV = Mimic.","Changes the ghost it copies every 30–120 s, so behaviour contradicts itself.","Can copy abilities and speeds, never another ghost's evidence."],tellsEl:["ΠΑΝΤΑ δείχνει Ghost Orbs ως ψεύτικη 4η απόδειξη – orbs μαζί με Spirit Box / Freezing / UV = Mimic.","Αλλάζει το φάντασμα που μιμείται κάθε 30–120 δ, οπότε η συμπεριφορά αντιφάσκει.","Αντιγράφει ικανότητες και ταχύτητες, ποτέ τις αποδείξεις άλλου φαντάσματος."]},
  {id:"twins",name:"The Twins",evidence:["EMF","SPIRIT_BOX","FREEZING"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.5,speedMax:1.9,speedEn:"Each hunt rolls 50/50: 1.5 m/s (slow) or 1.9 m/s (fast) – one ghost, not two · normal line-of-sight speed-up on top",speedEl:"Κάθε κυνήγι παίζει 50/50: 1.5 m/s (αργό) ή 1.9 m/s (γρήγορο) – ένα φάντασμα, όχι δύο · κανονική επιτάχυνση με οπτική επαφή επιπλέον",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["It is ONE ghost that can also interact far away (up to ~8.5 m, ~17 m on large maps) 1–2 s after a normal interaction – so two interactions less than 2 s apart is conclusive.","The far interaction is remote: it never gives Freezing or Spirit Box there (EMF 5 can still appear), and it cannot trigger motion sensors or salt at both places.","Speed changes from hunt to hunt (some slightly slower, some faster than normal) – a hint, not proof."],tellsEl:["Είναι ΕΝΑ φάντασμα που μπορεί να αλληλεπιδράσει και μακριά (έως ~8,5 μ., ~17 μ. σε μεγάλους χάρτες) 1–2 δ. μετά από κανονική αλληλεπίδραση – δύο αλληλεπιδράσεις σε λιγότερο από 2 δ. είναι απόδειξη.","Η μακρινή αλληλεπίδραση είναι «εξ αποστάσεως»: εκεί δεν δίνει ποτέ Freezing ή Spirit Box (EMF 5 μπορεί), και δεν ενεργοποιεί αισθητήρες κίνησης ή αλάτι και στα δύο σημεία.","Η ταχύτητα αλλάζει από κυνήγι σε κυνήγι (άλλοτε λίγο πιο αργό, άλλοτε πιο γρήγορο από το κανονικό) – ένδειξη, όχι απόδειξη."]},
  {id:"wraith",name:"Wraith",evidence:["EMF","SPIRIT_BOX","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Never steps in salt: it passes over a salt pile without disturbing it, so there are never salt footprints. Conclusive – but an enraged Gallu does the same.","Teleports next to a random player outside hunts, leaving EMF 2 at floor level (1 in 3 times EMF 5) – EMF with no interaction nearby points to a Wraith.","Myths: it does not float, walk through walls or have quiet footsteps."],tellsEl:["Δεν πατά ποτέ σε αλάτι: περνά πάνω από τον σωρό χωρίς να τον ανακατέψει, άρα δεν υπάρχουν ποτέ πατημασιές από αλάτι. Απόδειξη – αλλά το ίδιο κάνει και ο εξαγριωμένος Gallu.","Τηλεμεταφέρεται δίπλα σε τυχαίο παίκτη εκτός κυνηγιού, αφήνοντας EMF 2 στο πάτωμα (1 στις 3 φορές EMF 5) – EMF χωρίς αλληλεπίδραση κοντά δείχνει Wraith.","Μύθοι: δεν αιωρείται, δεν περνά μέσα από τοίχους και δεν έχει αθόρυβα βήματα."]},
  {id:"yokai",name:"Yokai",evidence:["ORB","SPIRIT_BOX","DOTS"],huntAt:50,huntMin:50,huntMax:80,huntEn:"50% – 80% while players talk near it",huntEl:"50% – 80% όσο οι παίκτες μιλούν κοντά του",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["During a hunt it only hears voices and electronics within 2.5 m – talk freely from a distance.","Talking near it raises its activity and hunt threshold."],tellsEl:["Στο κυνήγι ακούει φωνές και ηλεκτρονικά μόνο εντός 2.5 μ. – μίλα ελεύθερα από μακριά.","Η ομιλία κοντά του ανεβάζει δραστηριότητα και όριο κυνηγιού."]},
  {id:"yurei",name:"Yurei",evidence:["ORB","FREEZING","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.7,speedMax:1.7,speedEn:"1.7 m/s",speedEl:"1.7 m/s",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:false,tellsEn:["Ability: smoothly closes one open door in its room all the way (no slam, no creak, EMF 2 on the door) and drains 15% sanity from everyone within 7.5 m. It needs an open door in its room – close them to disable it.","Outside hunts its door touches are all-or-nothing: a door it moves ends fully open or fully shut. A door nudged only a little outside a hunt rules a Yurei out.","Incense in its room keeps it there for 90 s with no roaming and no D.O.T.S. – motion sensors in the doorways confirm it."],tellsEl:["Ικανότητα: κλείνει ομαλά μια ανοιχτή πόρτα του δωματίου του μέχρι τέρμα (χωρίς χτύπημα ή τρίξιμο, EMF 2 στην πόρτα) και ρουφά 15% λογικής από όλους εντός 7,5 μ. Χρειάζεται ανοιχτή πόρτα στο δωμάτιό του – κλείστε τις για να το ακυρώσετε.","Εκτός κυνηγιού τα αγγίγματά του σε πόρτες είναι όλα-ή-τίποτα: η πόρτα καταλήγει τέρμα ανοιχτή ή τέρμα κλειστή. Πόρτα που κουνήθηκε λίγο εκτός κυνηγιού αποκλείει το Yurei.","Θυμίαμα στο δωμάτιό του το κρατά εκεί για 90 δ. χωρίς περιπλάνηση και χωρίς D.O.T.S. – αισθητήρες κίνησης στις πόρτες το επιβεβαιώνουν."]},
  {id:"kormos",name:"Kormos",evidence:["ORB","SPIRIT_BOX","UV"],huntAt:50,huntMin:50,huntMax:70,huntEn:"50% – 70% if a player sprints in its room",huntEl:"50% – 70% αν ένας παίκτης τρέξει μέσα στο δωμάτιό του",speedMin:1.7,speedMax:2.21,speedEn:"1.7 m/s · ×1.3 = 2.21 m/s while heading to a sound it heard · within 5 m with a clear view of a moving player it locks on and speeds up like a normal ghost",speedEl:"1.7 m/s · ×1.3 = 2.21 m/s όσο πηγαίνει προς ήχο που άκουσε · εντός 5 μ. με καθαρή θέα σε παίκτη που κινείται «κλειδώνει» και επιταχύνει σαν κανονικό φάντασμα",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:true,tellsEn:["Nearly blind: it hunts by sound – it hears sprinting from 30 m, walking from 15 m, crouch-walking from 10 m (same floor only), plus voices and electronics.","Standing still does not alert it, even right next to it – but a moving player within 5 m in clear view locks it on. Statue test: stay still with incense ready; if it passes by and only finds you once you walk, it is a Kormos.","Sprinting in its room lets it hunt from 70% sanity. Walk, do not run.","Never does the mist/airball event or chase-type ghost events. Freezing temperatures mean it is the Mimic, not a Kormos."],tellsEl:["Σχεδόν τυφλό: κυνηγά με τον ήχο – ακούει τρέξιμο από 30 μ., περπάτημα από 15 μ., σκυφτό περπάτημα από 10 μ. (μόνο στον ίδιο όροφο), συν φωνές και ηλεκτρονικά.","Αν στέκεσαι ακίνητος δεν σε αντιλαμβάνεται, ακόμη και δίπλα του – αλλά παίκτης που κινείται εντός 5 μ. σε καθαρή θέα το «κλειδώνει». Τεστ αγάλματος: μείνε ακίνητος με θυμίαμα έτοιμο· αν περάσει δίπλα σου και σε βρει μόνο όταν περπατήσεις, είναι Kormos.","Τρέξιμο μέσα στο δωμάτιό του το αφήνει να κυνηγήσει από 70% λογική. Περπάτα, μην τρέχεις.","Δεν κάνει ποτέ το event ομίχλης ούτε events «κυνηγητού». Παγωμένες θερμοκρασίες σημαίνουν Mimic, όχι Kormos."]},
  {id:"aswang",name:"Aswang",evidence:["FREEZING","WRITING","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:1.53,speedMax:1.53,speedEn:"1.53 m/s base – accelerates faster than any ghost on line of sight (7.5%/s instead of 5%/s): 2.53 m/s in ~9 s · never a fast base speed",speedEl:"1.53 m/s βάση – επιταχύνει πιο γρήγορα από κάθε φάντασμα με οπτική επαφή (7,5%/δ αντί 5%/δ): 2.53 m/s σε ~9 δ · ποτέ γρήγορη βασική ταχύτητα",los:true,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:true,tellsEn:["Cannot kill a player hidden in an official (blockable) spot such as a closet or locker: reaching one ends the hunt at once. At the start of the NEXT hunt it heads straight for that player's position, grace period included.","Unofficial hiding spots (or difficulties with zero hiding places) give no protection – it kills normally there.","Starts every hunt slower than normal and ramps up fast once it sees you; a single hunt with a fast base speed rules it out."],tellsEl:["Δεν μπορεί να σκοτώσει παίκτη κρυμμένο σε επίσημη κρυψώνα (ντουλάπα, locker – όσες μπλοκάρονται): μόλις φτάσει, το κυνήγι τελειώνει. Στην αρχή του ΕΠΟΜΕΝΟΥ κυνηγιού πάει κατευθείαν στη θέση αυτού του παίκτη, περίοδο χάριτος συμπεριλαμβανομένης.","Ανεπίσημες κρυψώνες (ή δυσκολίες με μηδέν κρυψώνες) δεν προστατεύουν – εκεί σκοτώνει κανονικά.","Ξεκινά κάθε κυνήγι πιο αργά από το κανονικό και ανεβάζει γρήγορα μόλις σε δει· ένα και μόνο κυνήγι με γρήγορη βασική ταχύτητα το αποκλείει."]},
  {id:"deildegast",name:"Deildegast",evidence:["EMF","WRITING","DOTS"],huntAt:50,huntMin:50,huntMax:50,huntEn:"50%",huntEl:"50%",speedMin:0.4,speedMax:3.0,speedEn:"3.0 m/s at the start · −0.1 m/s for every different object moved outside hunts (13 objects = normal 1.7, 26 = 0.4 m/s) · resets to 3.0 when a hunt ends or a crucifix burns · no LOS boost",speedEl:"3.0 m/s στην αρχή · −0.1 m/s για κάθε διαφορετικό αντικείμενο που μετακινείται εκτός κυνηγιού (13 αντικείμενα = κανονικό 1.7, 26 = 0.4 m/s) · επαναφορά στο 3.0 όταν τελειώσει κυνήγι ή καεί σταυρός · χωρίς επιτάχυνση LOS",los:false,fakeOrb:false,guaranteed:null,smudge:90,cooldown:25,isNew:true,tellsEn:["Starts every hunt at 3.0 m/s with no line-of-sight speed-up – a first hunt that fast, without acceleration, points to it; any speed-up on sight rules it out.","Throwables, light switches, the fuse box and taps count as moved objects; doors, equipment and cursed items do not. Dead players' interactions count too – the only ghost the dead can slow down.","The slowdown holds until a hunt ends or a crucifix burns – then it is back to 3.0 m/s, so keep moving new objects between hunts.","Touches doors and switches less than other ghosts (10% vs 25%). Added in v0.18.0 (2026)."],tellsEl:["Ξεκινά κάθε κυνήγι με 3.0 m/s χωρίς επιτάχυνση οπτικής επαφής – τόσο γρήγορο πρώτο κυνήγι χωρίς επιτάχυνση δείχνει Deildegast· οποιαδήποτε επιτάχυνση όταν σε δει το αποκλείει.","Μετρούν τα πετούμενα αντικείμενα, οι διακόπτες φώτων, ο πίνακας και οι βρύσες· όχι πόρτες, εξοπλισμός και καταραμένα. Μετρούν και οι αλληλεπιδράσεις των νεκρών – το μόνο φάντασμα που επιβραδύνουν οι νεκροί.","Η επιβράδυνση κρατά μέχρι να τελειώσει κυνήγι ή να καεί σταυρός – τότε ξαναγίνεται 3.0 m/s, γι' αυτό μετακινείτε νέα αντικείμενα ανάμεσα στα κυνήγια.","Αγγίζει πόρτες και διακόπτες λιγότερο από τα άλλα (10% αντί 25%). Προστέθηκε στην v0.18.0 (2026)."]},
];
